// ===== Helpers =====

export function normalizeName(name) {
  return (name || '').toLowerCase().replace(/[^a-z0-9]+/g, ' ').trim();
}

export function searchExercises(query, filters = {}, library = EXERCISES) {
  const { muscle = 'All', equipment = 'All', movement = 'All', difficulty = 'All', category = 'All' } = filters;
  const q = (query || '').toLowerCase().trim();
  return library.filter((ex) => {
    if (muscle !== 'All' && ex.muscle_group !== muscle) return false;
    if (equipment !== 'All' && !(ex.equipment || []).includes(equipment)) return false;
    if (movement !== 'All' && ex.movement_pattern !== movement) return false;
    if (difficulty !== 'All' && ex.difficulty !== difficulty) return false;
    if (category !== 'All' && ex.category !== category) return false;
    if (q) {
      const hay = `${ex.name} ${ex.primary_muscle} ${(ex.secondary_muscles || []).join(' ')} ${(ex.equipment || []).join(' ')} ${ex.movement_pattern} ${ex.muscle_group}`.toLowerCase();
      if (!hay.includes(q)) return false;
    }
    return true;
  });
}

// Rule-based substitutions: same primary muscle + same movement pattern,
// different exercise, filtered by available equipment when provided.
export function getSubstitutions(exercise, availableEquipment = null) {
  if (!exercise) return [];
  const avail = availableEquipment && availableEquipment.length ? availableEquipment : null;
  const pool = EXERCISES.filter((e) => e.slug !== exercise.slug && e.primary_muscle === exercise.primary_muscle);
  // Prefer same movement pattern first, then same muscle group
  const samePattern = pool.filter((e) => e.movement_pattern === exercise.movement_pattern);
  const sameGroup = pool.filter((e) => e.muscle_group === exercise.muscle_group && e.movement_pattern !== exercise.movement_pattern);
  let ranked = [...samePattern, ...sameGroup];
  if (avail) {
    // Prioritize exercises whose equipment is fully available
    ranked = ranked.sort((a, b) => {
      const aOk = (a.equipment || []).every((eq) => avail.includes(eq)) ? 0 : 1;
      const bOk = (b.equipment || []).every((eq) => avail.includes(eq)) ? 0 : 1;
      return aOk - bOk;
    });
  }
  // Dedupe by slug
  const seen = new Set();
  return ranked.filter((e) => { if (seen.has(e.slug)) return false; seen.add(e.slug); return true; }).slice(0, 6);
}

// Merge the static library with the user's custom exercises from the Exercise entity.
// Custom exercises that match a default by normalized name are skipped (no duplicates).
let _exerciseCache = null;
let _exerciseCachePromise = null;
let _exerciseCacheTime = 0;

export function clearExerciseCache() { _exerciseCache = null; _exerciseCachePromise = null; _exerciseCacheTime = 0; }

export async function getAllExercises() {
  if (_exerciseCache && Date.now() - _exerciseCacheTime < 60000) return _exerciseCache;
  if (_exerciseCachePromise) return _exerciseCachePromise;
  _exerciseCachePromise = (async () => {
    let custom = [];
    try {
      const { base44 } = await import('@/api/base44Client');
      custom = (await base44.entities.Exercise.list('-created_date', 200)) || [];
    } catch (e) { /* ignore — static library still works */ }
    const defaultNames = new Set(EXERCISES.map((e) => normalizeName(e.name)));
    const customs = custom.filter((c) => c.name && !defaultNames.has(normalizeName(c.name)));
    _exerciseCache = [...EXERCISES, ...customs.map(adaptCustomExercise)];
    _exerciseCacheTime = Date.now();
    return _exerciseCache;
  })();
  try { return await _exerciseCachePromise; }
  finally { _exerciseCachePromise = null; }
}

// Adapt a custom Exercise entity record to the same shape as a static entry.
export function adaptCustomExercise(c) {
  return {
    slug: c.canonical_id || `custom-${c.id}`,
    name: c.name,
    muscle_group: c.subcategory || 'Other',
    primary_muscle: c.primary_muscle || 'Other',
    secondary_muscles: c.secondary_muscles || [],
    equipment: c.equipment || [],
    category: c.category || 'Resistance',
    movement_pattern: c.movement_pattern || 'Other',
    force_type: 'Other',
    laterality: c.unilateral ? 'Unilateral' : 'Bilateral',
    difficulty: c.difficulty || 'Beginner',
    rep_low: c.rep_range_low || 8,
    rep_high: c.rep_range_high || 12,
    rest: c.rest_seconds || 60,
    instructions: c.instructions || '',
    mistakes: c.common_mistakes || [],
    safety: c.safety_tips || [],
    alternatives: c.alternatives || [],
    custom: true,
    id: c.id,
  };
}